use pfx_vector_core::Path;
use super::{normalize_path_commands,SvgPathCommand};
#[derive(Clone,Debug,PartialEq)]pub struct SvgDiagnostic{pub message:String,pub start:usize,pub end:usize}
#[derive(Clone,Debug,PartialEq)]pub struct SvgError{pub diagnostic:SvgDiagnostic}
impl core::fmt::Display for SvgError{fn fmt(&self,f:&mut core::fmt::Formatter<'_>)->core::fmt::Result{write!(f,"{} at {}..{}",self.diagnostic.message,self.diagnostic.start,self.diagnostic.end)}} impl std::error::Error for SvgError{}
struct Parser<'a>{s:&'a str,pos:usize} impl<'a>Parser<'a>{fn new(s:&'a str)->Self{Self{s,pos:0}}fn b(&self)->&[u8]{self.s.as_bytes()}fn skip(&mut self){while let Some(c)=self.b().get(self.pos){if c.is_ascii_whitespace()||*c==b','{self.pos+=1}else{break}}}fn cmd(&mut self)->Option<u8>{self.skip();let c=*self.b().get(self.pos)?;if c.is_ascii_alphabetic(){self.pos+=1;Some(c)}else{None}}fn has_num(&mut self)->bool{self.skip();matches!(self.b().get(self.pos),Some(b'+'|b'-'|b'.'|b'0'..=b'9'))}fn num(&mut self)->Result<f64,SvgError>{self.skip();let st=self.pos;let b=self.b();if matches!(b.get(self.pos),Some(b'+'|b'-')){self.pos+=1}let mut dig=false;while matches!(b.get(self.pos),Some(b'0'..=b'9')){dig=true;self.pos+=1}if b.get(self.pos)==Some(&b'.'){self.pos+=1;while matches!(b.get(self.pos),Some(b'0'..=b'9')){dig=true;self.pos+=1}}if !dig{return Err(SvgError{diagnostic:SvgDiagnostic{message:"expected number".into(),start:st,end:self.pos}})}if matches!(b.get(self.pos),Some(b'e'|b'E')){let save=self.pos;self.pos+=1;if matches!(b.get(self.pos),Some(b'+'|b'-')){self.pos+=1}let es=self.pos;while matches!(b.get(self.pos),Some(b'0'..=b'9')){self.pos+=1}if es==self.pos{self.pos=save}}let v:self::f64=self.s[st..self.pos].parse().map_err(|_|SvgError{diagnostic:SvgDiagnostic{message:"invalid number".into(),start:st,end:self.pos}})?;if !v.is_finite(){return Err(SvgError{diagnostic:SvgDiagnostic{message:"non-finite number".into(),start:st,end:self.pos}})}Ok(v)}fn flag(&mut self)->Result<bool,SvgError>{self.skip();match self.b().get(self.pos){Some(b'0')=>{self.pos+=1;Ok(false)},Some(b'1')=>{self.pos+=1;Ok(true)},_=>Err(SvgError{diagnostic:SvgDiagnostic{message:"expected arc flag".into(),start:self.pos,end:self.pos+1}})}}}
pub fn parse_path_commands(data:&str)->Result<Vec<SvgPathCommand>,SvgError>{let mut p=Parser::new(data);let mut out=Vec::new();let mut active=None;let mut move_first=false;loop{p.skip();if p.pos>=data.len(){break}if let Some(c)=p.cmd(){active=Some(c);move_first=matches!(c,b'M'|b'm');if matches!(c,b'Z'|b'z'){out.push(SvgPathCommand::Close);active=None;continue}}let c=active.ok_or_else(||SvgError{diagnostic:SvgDiagnostic{message:"expected SVG path command".into(),start:p.pos,end:(p.pos+1).min(data.len())}})?;let rel=c.is_ascii_lowercase();let u=c.to_ascii_uppercase();if !p.has_num(){return Err(SvgError{diagnostic:SvgDiagnostic{message:"expected command parameters".into(),start:p.pos,end:p.pos}})}loop{let cmd=match u{b'M'=>{let x=p.num()?;let y=p.num()?;if move_first{move_first=false;SvgPathCommand::Move{relative:rel,x,y}}else{SvgPathCommand::Line{relative:rel,x,y}}},b'L'=>SvgPathCommand::Line{relative:rel,x:p.num()?,y:p.num()?},b'H'=>SvgPathCommand::Horizontal{relative:rel,x:p.num()?},b'V'=>SvgPathCommand::Vertical{relative:rel,y:p.num()?},b'C'=>SvgPathCommand::Cubic{relative:rel,x1:p.num()?,y1:p.num()?,x2:p.num()?,y2:p.num()?,x:p.num()?,y:p.num()?},b'S'=>SvgPathCommand::SmoothCubic{relative:rel,x2:p.num()?,y2:p.num()?,x:p.num()?,y:p.num()?},b'Q'=>SvgPathCommand::Quadratic{relative:rel,x1:p.num()?,y1:p.num()?,x:p.num()?,y:p.num()?},b'T'=>SvgPathCommand::SmoothQuadratic{relative:rel,x:p.num()?,y:p.num()?},b'A'=>SvgPathCommand::Arc{relative:rel,rx:p.num()?,ry:p.num()?,rotation:p.num()?,large_arc:p.flag()?,sweep:p.flag()?,x:p.num()?,y:p.num()?},_=>return Err(SvgError{diagnostic:SvgDiagnostic{message:"unsupported command".into(),start:p.pos.saturating_sub(1),end:p.pos}})};out.push(cmd);p.skip();if p.pos>=data.len()||p.b()[p.pos].is_ascii_alphabetic()||!p.has_num(){break}}}Ok(out)}
pub fn parse_path(data:&str)->Result<Path,SvgError>{let commands=parse_path_commands(data)?;normalize_path_commands(&commands).map_err(|e|SvgError{diagnostic:SvgDiagnostic{message:format!("geometry normalization failed: {e}"),start:0,end:data.len().min(1)}})}
